1	import type { SeaMapDefinition } from "@pirate-sea-race/content";
2	import type { TestRuins, TestRuinSetting } from "@pirate-sea-race/protocol";
3	import { unlockSource, type LedgerState } from "@pirate-sea-race/simulation/objectives";
4	import { createRuins, type RuinIsland, type RuinKind, type RuinsState } from "@pirate-sea-race/simulation/ruins";
5	
6	/**
7	 * The room's side of the ruins (`docs/ruins.md`, §3): which islands have one, the seed they are dealt from, and the
8	 * test-only settings. The ruins module itself decides every open, answer, lockout and unlock.
9	 */
10	
11	/** Every regular island with its ledger source ids (`source-<island>-<slot>`), in island order: the islands with a ruin. */
12	export function ruinIslandsOf(ledger: LedgerState): RuinIsland[] {
13	  const byIsland = new Map<number, string[]>();
14	  for (const source of ledger.sources) byIsland.set(source.island, [...(byIsland.get(source.island) ?? []), source.id]);
15	  return [...byIsland.entries()].sort(([a], [b]) => a - b).map(([island, sourceIds]) => ({ island, sourceIds }));
16	}
17	
18	/** A test-only ruin setting for one island: its own, else the `*` one, else none. */
19	export function testRuinSetting(settings: TestRuins | undefined, island: number): TestRuinSetting | undefined {
20	  return settings?.[String(island)] ?? settings?.["*"];
21	}
22	
23	/** How many derived seeds a pinned kind may try before the room gives up: each island's kind is one fair draw. */
24	export const RUIN_PIN_TRIES = 256;
25	
26	export interface MatchRuinsOptions {
27	  readonly islands: readonly RuinIsland[];
28	  /**
29	   * The ruins' seeds, derived from the match's master secret: `seed(0)` is the ruins' own (`deriveSeed(secret,
30	   * "ruins")`); `seed(n)` for n > 0 is only tried to meet a test-only pinned kind.
31	   */
32	  readonly seed: (attempt: number) => number;
33	  readonly settings?: TestRuins | undefined;
34	}
35	
36	export interface MatchRuins {
37	  readonly ruins: RuinsState;
38	  /** The seed the ruins were dealt from. */
39	  readonly seed: number;
40	  /** Test-only: islands whose sources are open from the start. */
41	  readonly openIslands: readonly number[];
42	}
43	
44	/**
45	 * A match's ruins, dealt once at its creation from the ruins' own seed (never the ledger's, so a clue says nothing of the
46	 * deal, and never the public match code). Test-only settings may pin an island's kind: the room then takes the first
47	 * of the ruins' derived seeds that deals every pinned kind, or open an island from the start.
48	 */
49	export function createMatchRuins(options: MatchRuinsOptions): MatchRuins {
50	  const pins = new Map<number, RuinKind>();
51	  const openIslands: number[] = [];
52	  for (const { island } of options.islands) {
53	    const setting = testRuinSetting(options.settings, island);
54	    if (setting === "open") openIslands.push(island);
55	    else if (setting !== undefined) pins.set(island, setting);
56	  }
57	  for (let attempt = 0; attempt < RUIN_PIN_TRIES; attempt++) {
58	    const seed = options.seed(attempt);
59	    const ruins = createRuins({ seed, islands: options.islands });
60	    if ([...pins].every(([island, kind]) => ruins.ruins[String(island)]?.puzzle.kind === kind)) return { ruins, seed, openIslands };
61	  }
62	  throw new Error(`no ruins seed in ${RUIN_PIN_TRIES} tries deals the pinned kinds`);
63	}
64	
65	/** Test-only: unlocks the sources of islands a test opened from the start, in the ledger. */
66	export function openIslandsInLedger(ledger: LedgerState, islands: readonly number[]): LedgerState {
67	  let next = ledger;
68	  for (const source of ledger.sources) if (islands.includes(source.island)) next = unlockSource(next, { sourceId: source.id, tick: 0 }).state;
69	  return next;
70	}
71	
72	/** Whether every source of an island is unlocked in the ledger: its ruin was solved (or a test opened it). */
73	export function islandUnlocked(ledger: LedgerState, island: number): boolean {
74	  const sources = ledger.sources.filter((source) => source.island === island);
75	  return sources.length > 0 && sources.every((source) => source.unlocked);
76	}
77	
78	/** The island a dock belongs to, or null (at sea, or a dock of no island). */
79	export function islandOfDock(map: SeaMapDefinition, dock: number): number | null {
80	  const island = map.docks[dock]?.island;
81	  return island === undefined || island < 0 ? null : island;
82	}
83	
84	/** The centre of an island's rectangle, in sub-units: where its ruin's marker stands for players in sight. */
85	export function islandCentre(map: SeaMapDefinition, island: number): { x: number; y: number } {
86	  const rect = map.islands[island];
87	  if (rect === undefined) throw new RangeError(`no island ${island}`);
88	  return { x: Math.floor(((rect.tileX * 2 + rect.widthTiles) * map.subUnitsPerTile) / 2), y: Math.floor(((rect.tileY * 2 + rect.heightTiles) * map.subUnitsPerTile) / 2) };
89	}
90	
91	/**
92	 * The point of an island's rectangle nearest a position, in sub-units: an island is in a player's sight when this point
93	 * is (§16), so a ship off its shore sees it however large it is.
94	 */
95	export function nearestIslandPoint(map: SeaMapDefinition, island: number, x: number, y: number): { x: number; y: number } {
96	  const rect = map.islands[island];
97	  if (rect === undefined) throw new RangeError(`no island ${island}`);
98	  const tile = map.subUnitsPerTile;
99	  const clamp = (value: number, low: number, high: number) => Math.min(Math.max(value, low), high);
100	  return { x: clamp(x, rect.tileX * tile, (rect.tileX + rect.widthTiles) * tile), y: clamp(y, rect.tileY * tile, (rect.tileY + rect.heightTiles) * tile) };
101	}
102	
103	/** Verdicts a player's request ids are remembered for: a retry of any of the last this many gets its first verdict. */
104	export const REMEMBERED_RUIN_REQUESTS = 16;
105	
106	/** A player's recent answers by request id, oldest first, at most `REMEMBERED_RUIN_REQUESTS`. */
107	export class RuinRequests<T> {
108	  private readonly byPlayer = new Map<string, Map<string, T>>();
109	
110	  get(playerId: string, requestId: string): T | undefined {
111	    return this.byPlayer.get(playerId)?.get(requestId);
112	  }
113	
114	  remember(playerId: string, requestId: string, verdict: T): void {
115	    const entries = this.byPlayer.get(playerId) ?? new Map<string, T>();
116	    entries.set(requestId, verdict);
117	    if (entries.size > REMEMBERED_RUIN_REQUESTS) entries.delete(entries.keys().next().value!);
118	    this.byPlayer.set(playerId, entries);
119	  }
120	
