1	import { RUIN_MOVES, type RuinSymbol } from "@pirate-sea-race/content/ruins";
2	import { attemptSolves, type RuinAttempt, type RuinClue } from "./puzzles.js";
3	import {
4	  clueFor,
5	  findRuin,
6	  hasSolved,
7	  lockedUntil,
8	  presenceOf,
9	  sessionOf,
10	  type Ruin,
11	  type RuinPresence,
12	  type RuinsState,
13	} from "./state.js";
14	
15	/**
16	 * Why a request changed nothing (§16: duplicate, stale or refused requests return the current result without
17	 * mutating state). A rejected request always returns the very state object it was given. No rejection depends on the
18	 * answer: a malformed attempt is refused for its shape alone, and a well-formed wrong one is a wrong answer.
19	 */
20	export type RuinRejection =
21	  | "invalid-request"
22	  | "stale-tick"
23	  | "duplicate"
24	  | "unknown-ruin"
25	  | "not-at-ruin"
26	  | "in-duel"
27	  | "no-session"
28	  | "already-solved"
29	  | "locked-out";
30	
31	/**
32	 * What the caller applies to the ledger later:
33	 * - `sources-unlocked`: the first solve of a ruin, once per ruin; `unlockSource` for each id.
34	 * - `gold-awarded`: a player's first solve of a ruin, once per player and ruin; new gold (§11).
35	 */
36	export type RuinEvent =
37	  | { readonly kind: "sources-unlocked"; readonly island: number; readonly sourceIds: readonly string[]; readonly playerId: string; readonly tick: number }
38	  | { readonly kind: "gold-awarded"; readonly island: number; readonly playerId: string; readonly amount: number; readonly tick: number };
39	
40	/** What every operation returns: the next state (the same object when nothing changed) and its result. */
41	export interface RuinStep<R> {
42	  readonly state: RuinsState;
43	  readonly result: R;
44	}
45	
46	function isTick(value: unknown): value is number {
47	  return typeof value === "number" && Number.isSafeInteger(value) && value >= 0;
48	}
49	
50	function isPlayerId(value: unknown): value is string {
51	  return typeof value === "string" && value.length > 0;
52	}
53	
54	function isIsland(value: unknown): value is number {
55	  return typeof value === "number" && Number.isSafeInteger(value) && value >= 0;
56	}
57	
58	function tickRejection(state: RuinsState, tick: unknown): RuinRejection | null {
59	  if (!isTick(tick)) return "invalid-request";
60	  return tick < state.tick ? "stale-tick" : null;
61	}
62	
63	function byPlayer<T extends { readonly playerId: string }>(a: T, b: T): number {
64	  return a.playerId < b.playerId ? -1 : a.playerId > b.playerId ? 1 : 0;
65	}
66	
67	/** Puts (or with null, removes) a player's entry in a list sorted by player id. */
68	function upsert<T extends { readonly playerId: string }>(list: readonly T[], playerId: string, entry: T | null): T[] {
69	  const rest = list.filter((item) => item.playerId !== playerId);
70	  return entry === null ? rest : [...rest, entry].sort(byPlayer);
71	}
72	
73	function withRuin(state: RuinsState, ruin: Ruin): RuinsState {
74	  return { ...state, ruins: { ...state.ruins, [String(ruin.island)]: ruin } };
75	}
76	
77	// ---------------------------------------------------------------------------------------------------------------
78	// Presence
79	
80	export interface ReportPresenceRequest {
81	  readonly playerId: string;
82	  /** The island whose dock the player is moored at, or null when at sea (or anywhere without a ruin). */
83	  readonly island: number | null;
84	  readonly inDuel: boolean;
85	  readonly tick: number;
86	}
87	
88	export interface PresenceResult {
89	  readonly ok: boolean;
90	  readonly rejection: RuinRejection | null;
91	  /** The islands whose ruin session this report closed. */
92	  readonly closed: readonly number[];
93	}
94	
95	/**
96	 * The caller reports where a player is whenever it changes (it may report every tick; an unchanged report is a
97	 * duplicate). Being elsewhere than a ruin's island, or in a duel, closes the player's session there. Lockouts stay.
98	 */
99	export function reportPresence(state: RuinsState, request: ReportPresenceRequest): RuinStep<PresenceResult> {
100	  const { playerId, island, inDuel, tick } = request;
101	  const reject = (rejection: RuinRejection): RuinStep<PresenceResult> => ({ state, result: { ok: false, rejection, closed: [] } });
102	  const bad = tickRejection(state, tick);
103	  if (bad) return reject(bad);
104	  if (!isPlayerId(playerId) || (island !== null && !isIsland(island)) || typeof inDuel !== "boolean") return reject("invalid-request");
105	  const current = presenceOf(state, playerId);
106	  if (current.island === island && current.inDuel === inDuel) return reject("duplicate");
107	  const closed: number[] = [];
108	  const ruins: Record<string, Ruin> = { ...state.ruins };
109	  for (const [key, ruin] of Object.entries(state.ruins)) {
110	    if (!sessionOf(ruin, playerId) || (!inDuel && ruin.island === island)) continue;
111	    ruins[key] = { ...ruin, sessions: upsert(ruin.sessions, playerId, null) };
112	    closed.push(ruin.island);
113	  }
114	  const entry: RuinPresence | null = island === null && !inDuel ? null : { playerId, island, inDuel };
115	  const next: RuinsState = { ...state, tick, ruins, presence: upsert(state.presence, playerId, entry) };
116	  return { state: next, result: { ok: true, rejection: null, closed: closed.sort((a, b) => a - b) } };
117	}
118	
119	// ---------------------------------------------------------------------------------------------------------------
120	// Opening a ruin
121	
122	export interface OpenRuinRequest {
123	  readonly playerId: string;
124	  readonly island: number;
125	  readonly tick: number;
126	}
127	
128	export interface OpenResult {
129	  readonly ok: boolean;
130	  readonly rejection: RuinRejection | null;
131	  /** The clue, for a player with a session at this ruin (a repeated open gets it again); otherwise null. */
132	  readonly clue: RuinClue | null;
133	  /** The tick before which this player's attempts here are refused; 0 when never locked out. */
134	  readonly lockedUntil: number;
135	  /** Whether this player has already solved this ruin. */
136	  readonly solved: boolean;
137	}
138	
139	/** Starts a player's session at the ruin of the island they are moored at and hands them its clue. */
140	export function openRuin(state: RuinsState, request: OpenRuinRequest): RuinStep<OpenResult> {
141	  const { playerId, island, tick } = request;
142	  const ruin = isIsland(island) ? findRuin(state, island) : undefined;
143	  const reject = (rejection: RuinRejection): RuinStep<OpenResult> => {
144	    const session = ruin && isPlayerId(playerId) ? sessionOf(ruin, playerId) : undefined;
145	    return {
146	      state,
147	      result: {
148	        ok: false,
149	        rejection,
150	        clue: session ? clueFor(ruin!) : null,
151	        lockedUntil: ruin && isPlayerId(playerId) ? lockedUntil(ruin, playerId) : 0,
152	        solved: ruin !== undefined && isPlayerId(playerId) && hasSolved(ruin, playerId),
153	      },
154	    };
155	  };
156	  const bad = tickRejection(state, tick);
157	  if (bad) return reject(bad);
158	  if (!isPlayerId(playerId) || !isIsland(island)) return reject("invalid-request");
159	  if (!ruin) return reject("unknown-ruin");
160	  const presence = presenceOf(state, playerId);
161	  if (presence.inDuel) return reject("in-duel");
162	  if (presence.island !== island) return reject("not-at-ruin");
163	  if (sessionOf(ruin, playerId)) return reject("duplicate");
164	  const opened: Ruin = { ...ruin, sessions: upsert(ruin.sessions, playerId, { playerId, openedTick: tick }) };
165	  return {
166	    state: withRuin({ ...state, tick }, opened),
167	    result: { ok: true, rejection: null, clue: clueFor(opened), lockedUntil: lockedUntil(ruin, playerId), solved: hasSolved(ruin, playerId) },
168	  };
169	}
170	
171	// ---------------------------------------------------------------------------------------------------------------
172	// Answering
173	
174	export interface AnswerRuinRequest {
175	  readonly playerId: string;
176	  readonly island: number;
177	  readonly tick: number;
178	  readonly attempt: RuinAttempt;
179	}
180	
181	export type AnswerOutcome = "solved" | "wrong";
182	
183	export interface AnswerResult {
184	  readonly ok: boolean;
185	  readonly rejection: RuinRejection | null;
186	  readonly outcome: AnswerOutcome | null;
187	  /** The tick before which this player's attempts here are refused; 0 when never locked out. */
188	  readonly lockedUntil: number;
189	  /** For the caller to apply to the ledger, in order. */
190	  readonly events: readonly RuinEvent[];
191	}
192	
193	/**
194	 * Whether an attempt has a well-formed shape for the ruin's kind, which the clue already tells: a sequence of the
195	 * right length of distinct known symbols, or one to `size²` compass moves. The check never looks at the answer.
196	 */
197	function attemptShapeOk(state: RuinsState, ruin: Ruin, attempt: unknown): attempt is RuinAttempt {
198	  if (typeof attempt !== "object" || attempt === null) return false;
199	  const candidate = attempt as Record<string, unknown>;
200	  if (candidate.kind !== ruin.puzzle.kind) return false;
201	  if (ruin.puzzle.kind === "sequence") {
202	    const symbols = candidate.symbols;
203	    if (!Array.isArray(symbols) || symbols.length !== ruin.puzzle.answer.length) return false;
204	    const known: readonly string[] = state.rules.symbols;
205	    return symbols.every((symbol) => typeof symbol === "string" && known.includes(symbol)) && new Set(symbols as RuinSymbol[]).size === symbols.length;
206	  }
207	  const moves = candidate.moves;
208	  const longest = ruin.puzzle.size * ruin.puzzle.size;
209	  const compass: readonly string[] = RUIN_MOVES;
210	  return Array.isArray(moves) && moves.length > 0 && moves.length <= longest && moves.every((move) => typeof move === "string" && compass.includes(move));
211	}
212	
213	/**
214	 * Checks a player's attempt at the ruin they have open. A right answer solves the ruin for that player: the first
215	 * solve unlocks the island's sources for everyone, and every player's first solve pays the completion gold. A wrong
216	 * answer locks that player out of that ruin for `lockoutTicks`.
217	 */
218	export function answerRuin(state: RuinsState, request: AnswerRuinRequest): RuinStep<AnswerResult> {
219	  const { playerId, island, tick, attempt } = request;
220	  const ruin = isIsland(island) ? findRuin(state, island) : undefined;
221	  const reject = (rejection: RuinRejection): RuinStep<AnswerResult> => ({
222	    state,
223	    result: { ok: false, rejection, outcome: null, lockedUntil: ruin && isPlayerId(playerId) ? lockedUntil(ruin, playerId) : 0, events: [] },
224	  });
225	  const bad = tickRejection(state, tick);
226	  if (bad) return reject(bad);
227	  if (!isPlayerId(playerId) || !isIsland(island)) return reject("invalid-request");
228	  if (!ruin) return reject("unknown-ruin");
229	  const presence = presenceOf(state, playerId);
230	  if (presence.inDuel) return reject("in-duel");
231	  if (presence.island !== island) return reject("not-at-ruin");
232	  if (!sessionOf(ruin, playerId)) return reject("no-session");
233	  if (hasSolved(ruin, playerId)) return reject("already-solved");
234	  if (tick < lockedUntil(ruin, playerId)) return reject("locked-out");
235	  if (!attemptShapeOk(state, ruin, attempt)) return reject("invalid-request");
236	
237	  if (!attemptSolves(ruin.puzzle, attempt)) {
238	    const until = tick + state.rules.lockoutTicks;
239	    const locked: Ruin = { ...ruin, lockouts: upsert(ruin.lockouts, playerId, { playerId, until }) };
240	    return { state: withRuin({ ...state, tick }, locked), result: { ok: true, rejection: null, outcome: "wrong", lockedUntil: until, events: [] } };
241	  }
242	  const events: RuinEvent[] = [];
243	  if (!ruin.unlocked) events.push({ kind: "sources-unlocked", island: ruin.island, sourceIds: [...ruin.sourceIds], playerId, tick });
244	  events.push({ kind: "gold-awarded", island: ruin.island, playerId, amount: state.rules.completionGold, tick });
245	  const solved: Ruin = { ...ruin, unlocked: true, solvedBy: [...ruin.solvedBy, { playerId, tick }] };
246	  return {
247	    state: withRuin({ ...state, tick }, solved),
248	    result: { ok: true, rejection: null, outcome: "solved", lockedUntil: lockedUntil(ruin, playerId), events },
249	  };
250	}
