1	import { z } from "zod";
2	import { encodedSize } from "./input.js";
3	
4	/**
5	 * The ruin messages (protocol v8, §3 and §16). Every regular island's rubbings are locked behind its ruin. A player
6	 * moored at the island opens it (R) and gets its clue, then answers; the server alone knows the answer and judges it.
7	 * Whether an island is unlocked travels in the synced state; the clue and the verdict are messages to one player.
8	 */
9	export const RuinMessageType = {
10	  /** Client → server: open the ruin of the island this player is moored at (`OpenRuinMessage`). */
11	  Open: "open-ruin",
12	  /** Client → server: an answer to the ruin this player has open (`AnswerRuinMessage`). */
13	  Answer: "answer-ruin",
14	  /** Server → client: the clue of the ruin the player opened, to that player only (`RuinClueMessage`). */
15	  Clue: "ruin-clue",
