694	+import type { SeaMapDefinition } from "@pirate-sea-race/content";
695	+import type { TestRuins, TestRuinSetting } from "@pirate-sea-race/protocol";
696	+import { unlockSource, type LedgerState } from "@pirate-sea-race/simulation/objectives";
697	+import { createRuins, type RuinIsland, type RuinKind, type RuinsState } from "@pirate-sea-race/simulation/ruins";
698	+
699	+/**
700	+ * The room's side of the ruins (`docs/ruins.md`, §3): which islands have one, the seed they are dealt from, and the
701	+ * test-only settings. The ruins module itself decides every open, answer, lockout and unlock.
702	+ */
703	+
704	+/** Every regular island with its ledger source ids (`source-<island>-<slot>`), in island order: the islands with a ruin. */
705	+export function ruinIslandsOf(ledger: LedgerState): RuinIsland[] {
706	+  const byIsland = new Map<number, string[]>();
707	+  for (const source of ledger.sources) byIsland.set(source.island, [...(byIsland.get(source.island) ?? []), source.id]);
708	+  return [...byIsland.entries()].sort(([a], [b]) => a - b).map(([island, sourceIds]) => ({ island, sourceIds }));
709	+}
710	+
711	+/** A test-only ruin setting for one island: its own, else the `*` one, else none. */
712	+export function testRuinSetting(settings: TestRuins | undefined, island: number): TestRuinSetting | undefined {
713	+  return settings?.[String(island)] ?? settings?.["*"];
714	+}
715	+
716	+/** How many derived seeds a pinned kind may try before the room gives up: each island's kind is one fair draw. */
717	+export const RUIN_PIN_TRIES = 256;
718	+
719	+export interface MatchRuinsOptions {
720	+  readonly islands: readonly RuinIsland[];
721	+  /**
722	+   * The ruins' seeds, derived from the match's master secret: `seed(0)` is the ruins' own (`deriveSeed(secret,
723	+   * "ruins")`); `seed(n)` for n > 0 is only tried to meet a test-only pinned kind.
724	+   */
725	+  readonly seed: (attempt: number) => number;
726	+  readonly settings?: TestRuins | undefined;
727	+}
728	+
729	+export interface MatchRuins {
730	+  readonly ruins: RuinsState;
731	+  /** The seed the ruins were dealt from. */
732	+  readonly seed: number;
733	+  /** Test-only: islands whose sources are open from the start. */
734	+  readonly openIslands: readonly number[];
735	+}
736	+
737	+/**
738	+ * A match's ruins, dealt once at its creation from the ruins' own seed (never the ledger's, so a clue says nothing of the
739	+ * deal, and never the public match code). Test-only settings may pin an island's kind: the room then takes the first
740	+ * of the ruins' derived seeds that deals every pinned kind, or open an island from the start.
741	+ */
742	+export function createMatchRuins(options: MatchRuinsOptions): MatchRuins {
743	+  const pins = new Map<number, RuinKind>();
744	+  const openIslands: number[] = [];
745	+  for (const { island } of options.islands) {
746	+    const setting = testRuinSetting(options.settings, island);
747	+    if (setting === "open") openIslands.push(island);
748	+    else if (setting !== undefined) pins.set(island, setting);
749	+  }
750	+  for (let attempt = 0; attempt < RUIN_PIN_TRIES; attempt++) {
751	+    const seed = options.seed(attempt);
752	+    const ruins = createRuins({ seed, islands: options.islands });
753	+    if ([...pins].every(([island, kind]) => ruins.ruins[String(island)]?.puzzle.kind === kind)) return { ruins, seed, openIslands };
754	+  }
755	+  throw new Error(`no ruins seed in ${RUIN_PIN_TRIES} tries deals the pinned kinds`);
756	+}
757	+
758	+/** Test-only: unlocks the sources of islands a test opened from the start, in the ledger. */
759	+export function openIslandsInLedger(ledger: LedgerState, islands: readonly number[]): LedgerState {
760	+  let next = ledger;
761	+  for (const source of ledger.sources) if (islands.includes(source.island)) next = unlockSource(next, { sourceId: source.id, tick: 0 }).state;
762	+  return next;
763	+}
764	+
765	+/** Whether every source of an island is unlocked in the ledger: its ruin was solved (or a test opened it). */
766	+export function islandUnlocked(ledger: LedgerState, island: number): boolean {
767	+  const sources = ledger.sources.filter((source) => source.island === island);
768	+  return sources.length > 0 && sources.every((source) => source.unlocked);
769	+}
770	+
771	+/** The island a dock belongs to, or null (at sea, or a dock of no island). */
772	+export function islandOfDock(map: SeaMapDefinition, dock: number): number | null {
773	+  const island = map.docks[dock]?.island;
774	+  return island === undefined || island < 0 ? null : island;
775	+}
776	+
777	+/** The centre of an island's rectangle, in sub-units: where its ruin's marker stands for players in sight. */
778	+export function islandCentre(map: SeaMapDefinition, island: number): { x: number; y: number } {
779	+  const rect = map.islands[island];
780	+  if (rect === undefined) throw new RangeError(`no island ${island}`);
781	+  return { x: Math.floor(((rect.tileX * 2 + rect.widthTiles) * map.subUnitsPerTile) / 2), y: Math.floor(((rect.tileY * 2 + rect.heightTiles) * map.subUnitsPerTile) / 2) };
782	+}
783	+
784	+/**
785	+ * The point of an island's rectangle nearest a position, in sub-units: an island is in a player's sight when this point
786	+ * is (§16), so a ship off its shore sees it however large it is.
787	+ */
788	+export function nearestIslandPoint(map: SeaMapDefinition, island: number, x: number, y: number): { x: number; y: number } {
789	+  const rect = map.islands[island];
790	+  if (rect === undefined) throw new RangeError(`no island ${island}`);
791	+  const tile = map.subUnitsPerTile;
792	+  const clamp = (value: number, low: number, high: number) => Math.min(Math.max(value, low), high);
793	+  return { x: clamp(x, rect.tileX * tile, (rect.tileX + rect.widthTiles) * tile), y: clamp(y, rect.tileY * tile, (rect.tileY + rect.heightTiles) * tile) };
794	+}
795	+
796	+/** Verdicts a player's request ids are remembered for: a retry of any of the last this many gets its first verdict. */
797	+export const REMEMBERED_RUIN_REQUESTS = 16;
798	+
799	+/** A player's recent answers by request id, oldest first, at most `REMEMBERED_RUIN_REQUESTS`. */
800	+export class RuinRequests<T> {
801	+  private readonly byPlayer = new Map<string, Map<string, T>>();
802	+
803	+  get(playerId: string, requestId: string): T | undefined {
804	+    return this.byPlayer.get(playerId)?.get(requestId);
805	+  }
806	+
807	+  remember(playerId: string, requestId: string, verdict: T): void {
808	+    const entries = this.byPlayer.get(playerId) ?? new Map<string, T>();
809	+    entries.set(requestId, verdict);
810	+    if (entries.size > REMEMBERED_RUIN_REQUESTS) entries.delete(entries.keys().next().value!);
811	+    this.byPlayer.set(playerId, entries);
812	+  }
813	+
814	+  forget(playerId: string): void {
815	+    this.byPlayer.delete(playerId);
816	+  }
817	+}
