15	import { tabletText } from "@pirate-sea-race/simulation/ruins";
16	
17	/**
18	 * §3's ruins in the browser: the HUD's ruin line at an island, and the ruin panel. A player moored at an island whose
19	 * ruin they have not solved presses R; the server answers with the clue (to them only), which the panel lays out to
20	 * read at a glance: six tablets with their inscriptions, or the grid with its start, goal and blocked cells. The
21	 * answer is entered with clicks or keys (1–6 for symbols, the arrows or WASD for moves, Backspace to undo, Enter to
22	 * submit) and sent as `answer-ruin`; the server's verdict shows as a lockout countdown or as the gold and the unlock.
23	 * Everything below `RuinPanel` is plain data, for unit tests; `RuinPanel` and `applyRuin` touch the page.
24	 */
25	
26	/** This player's ruin fields from its private status. */
27	export interface RuinStatus {
28	  /** "locked", "unlocked", "solved", or "" away from an island with a ruin. */
29	  readonly ruin: string;
30	  readonly ruinOpen: boolean;
31	  readonly ruinLockedUntil: number;
32	}
33	
34	/** An island's ruin marker as the server sent it: only islands in sight, or where the player is moored. */
35	export interface RuinMarker {
36	  readonly island: number;
37	  readonly unlocked: boolean;
38	}
39	
40	export interface Line {
41	  readonly text: string;
42	  readonly state: string;
43	  readonly seconds?: number;
44	}
45	
46	const SYMBOLS: Readonly<Record<RuinSymbolName, { readonly name: string; readonly glyph: string }>> = {
47	  sun: { name: "Sun", glyph: "☀" },
48	  moon: { name: "Moon", glyph: "☾" },
49	  tide: { name: "Tide", glyph: "≈" },
50	  storm: { name: "Storm", glyph: "ϟ" },
51	  anchor: { name: "Anchor", glyph: "⚓" },
52	  skull: { name: "Skull", glyph: "☠" },
53	};
54	
55	/** Whole seconds left until a world tick, rounded up; 0 once it has passed. */
56	function secondsUntil(tick: number, worldTick: number): number {
57	  return Math.max(0, Math.ceil((tick - worldTick) / WORLD_STEPS_PER_SECOND));
58	}
59	
60	/**
61	 * The HUD's ruin line at the island the player is moored at (the Island line names it): sealed (press R), opened by
62	 * someone else (R still pays the solver's gold), or solved by this player. Nothing away from a ruin.
63	 */
64	export function ruinLine(status: RuinStatus | undefined): Line {
65	  switch (status?.ruin) {
66	    case "locked":
67	      return { text: "Sealed: rubbings locked. Press R for the clue", state: "locked" };
68	    case "unlocked":
69	      return { text: "Opened by another captain. R: solve it too (+40 gold)", state: "unlocked" };
70	    case "solved":
71	      return { text: "Solved by you", state: "solved" };
72	    default:
73	      return { text: "", state: "none" };
74	  }
75	}
76	
77	/** Whether R opens a ruin now: moored at an island whose ruin this player has not solved. */
78	export function canOpenRuin(status: RuinStatus | undefined): boolean {
79	  return status?.ruin === "locked" || status?.ruin === "unlocked";
80	}
81	
82	/** The ruins of islands in sight (or where moored): "Palm Key: sealed, Ember Rock: open". */
83	export function sightedRuinsLine(markers: readonly RuinMarker[], islandName: (island: number) => string): Line {
84	  if (markers.length === 0) return { text: "", state: "none" };
85	  const sorted = [...markers].sort((a, b) => a.island - b.island);
86	  return {
87	    text: sorted.map((marker) => `${islandName(marker.island)}: ${marker.unlocked ? "open" : "sealed"}`).join(", "),
88	    state: sorted.map((marker) => `${marker.island}:${marker.unlocked ? "open" : "sealed"}`).join(","),
89	  };
90	}
91	
92	// ---------------------------------------------------------------------------------------------------------------
93	// The clue, laid out
94	
95	export interface TabletView {
96	  /** 1 to 6: the key and the display order. */
97	  readonly key: number;
98	  readonly symbol: RuinSymbolName;
99	  readonly name: string;
100	  readonly glyph: string;
101	  /** The inscription, such as "Tide comes right after Sun". */
102	  readonly text: string;
103	}
104	
105	export type CellKind = "start" | "goal" | "blocked" | "open";
106	
107	export interface CellView {
108	  readonly x: number;
109	  readonly y: number;
110	  readonly kind: CellKind;
111	}
112	
113	/** The six tablets in display order, each with its key, glyph and inscription. */
114	export function tabletsOf(clue: Extract<RuinClueMessage, { kind: "sequence" }>): TabletView[] {
115	  return clue.tablets.map((tablet, index) => ({
116	    key: index + 1,
117	    symbol: tablet.symbol,
118	    name: SYMBOLS[tablet.symbol].name,
119	    glyph: SYMBOLS[tablet.symbol].glyph,
120	    text: tabletText(tablet, clue.length),
121	  }));
122	}
123	
124	/** The grid row by row from the north: each cell the start, the goal, blocked or open. */
125	export function gridOf(clue: Extract<RuinClueMessage, { kind: "navigation" }>): CellView[][] {
126	  const blocked = new Set(clue.blocked.map((cell) => `${cell.x},${cell.y}`));
127	  return Array.from({ length: clue.size }, (_, y) =>
128	    Array.from({ length: clue.size }, (_, x) => {
129	      const kind: CellKind =
130	        x === clue.start.x && y === clue.start.y ? "start" : x === clue.goal.x && y === clue.goal.y ? "goal" : blocked.has(`${x},${y}`) ? "blocked" : "open";
131	      return { x, y, kind };
132	    }),
133	  );
134	}
135	
136	// ---------------------------------------------------------------------------------------------------------------
137	// Entering the answer
138	
139	const MOVE_KEYS: Readonly<Record<string, RuinMoveName>> = {
140	  ArrowUp: "N",
141	  KeyW: "N",
142	  ArrowRight: "E",
143	  KeyD: "E",
144	  ArrowDown: "S",
145	  KeyS: "S",
146	  ArrowLeft: "W",
147	  KeyA: "W",
148	};
149	const STEPS: Readonly<Record<RuinMoveName, { x: number; y: number }>> = { N: { x: 0, y: -1 }, E: { x: 1, y: 0 }, S: { x: 0, y: 1 }, W: { x: -1, y: 0 } };
150	/** The longest path the panel takes: a 4 × 4 grid's every cell. */
151	const MAX_PATH_MOVES = 16;
152	
153	/** What a key does in the panel. */
154	export type PanelKey = { kind: "symbol"; symbol: RuinSymbolName } | { kind: "move"; move: RuinMoveName } | { kind: "undo" } | { kind: "submit" } | { kind: "close" };
155	
156	/** A key (its `KeyboardEvent.code`) in a panel showing a clue of this kind, or undefined for a key it does not use. */
157	export function panelKey(kind: RuinClueMessage["kind"], code: string): PanelKey | undefined {
158	  if (code === "Backspace") return { kind: "undo" };
159	  if (code === "Enter" || code === "NumpadEnter") return { kind: "submit" };
160	  if (code === "Escape") return { kind: "close" };
161	  if (kind === "sequence") {
162	    const digit = /^(?:Digit|Numpad)([1-6])$/.exec(code)?.[1];
163	    return digit === undefined ? undefined : { kind: "symbol", symbol: RUIN_SYMBOL_NAMES[Number(digit) - 1]! };
164	  }
165	  const move = MOVE_KEYS[code];
166	  return move === undefined ? undefined : { kind: "move", move };
167	}
168	
169	/** The answer being entered: symbols in order for a sequence, moves for a grid. */
170	export interface Entry {
171	  readonly symbols: readonly RuinSymbolName[];
172	  readonly moves: readonly RuinMoveName[];
173	}
174	
175	export const EMPTY_ENTRY: Entry = { symbols: [], moves: [] };
176	
177	/** The cells a path visits, from the start: one more than its moves. */
178	export function pathCells(clue: Extract<RuinClueMessage, { kind: "navigation" }>, moves: readonly RuinMoveName[]): { x: number; y: number }[] {
179	  const cells = [{ ...clue.start }];
180	  for (const move of moves) {
181	    const last = cells.at(-1)!;
182	    cells.push({ x: last.x + STEPS[move].x, y: last.y + STEPS[move].y });
183	  }
184	  return cells;
185	}
186	
187	/**
188	 * The entry after one key or click. A sequence takes a symbol not yet chosen until it is complete; a path takes a move
189	 * that stays on the grid and off the blocked cells. Undo takes the last one back. Anything else changes nothing.
190	 */
191	export function enter(clue: RuinClueMessage, entry: Entry, key: PanelKey): Entry {
192	  if (key.kind === "undo") return clue.kind === "sequence" ? { ...entry, symbols: entry.symbols.slice(0, -1) } : { ...entry, moves: entry.moves.slice(0, -1) };
193	  if (key.kind === "symbol" && clue.kind === "sequence") {
194	    if (entry.symbols.includes(key.symbol) || entry.symbols.length >= clue.length) return entry;
195	    return { ...entry, symbols: [...entry.symbols, key.symbol] };
196	  }
197	  if (key.kind === "move" && clue.kind === "navigation") {
198	    if (entry.moves.length >= MAX_PATH_MOVES) return entry;
199	    const at = pathCells(clue, entry.moves).at(-1)!;
200	    const next = { x: at.x + STEPS[key.move].x, y: at.y + STEPS[key.move].y };
201	    const off = next.x < 0 || next.y < 0 || next.x >= clue.size || next.y >= clue.size;
202	    if (off || clue.blocked.some((cell) => cell.x === next.x && cell.y === next.y)) return entry;
203	    return { ...entry, moves: [...entry.moves, key.move] };
204	  }
205	  return entry;
206	}
207	
208	/** The attempt to send, once the entry is complete: every symbol of the sequence, or a path that ends on the goal. */
209	export function attemptOf(clue: RuinClueMessage, entry: Entry): AnswerRuinMessage["attempt"] | undefined {
210	  if (clue.kind === "sequence") return entry.symbols.length === clue.length ? { kind: "sequence", symbols: [...entry.symbols] } : undefined;
211	  const end = pathCells(clue, entry.moves).at(-1)!;
212	  // The start is never the goal, so an empty path never ends there.
213	  return end.x === clue.goal.x && end.y === clue.goal.y ? { kind: "navigation", moves: [...entry.moves] } : undefined;
214	}
215	
216	/** The entry as the panel writes it: "☀ Sun → ≈ Tide → _" or "N E E S". */
217	export function entryText(clue: RuinClueMessage, entry: Entry): string {
218	  if (clue.kind === "sequence") {
219	    const chosen = entry.symbols.map((symbol) => `${SYMBOLS[symbol].glyph} ${SYMBOLS[symbol].name}`);
220	    return [...chosen, ...Array.from({ length: clue.length - chosen.length }, () => "_")].join(" → ");
221	  }
222	  return entry.moves.length === 0 ? "Start at S; walk to G" : entry.moves.join(" ");
223	}
224	
225	// ---------------------------------------------------------------------------------------------------------------
226	// Verdicts
227	
228	const REFUSALS: Readonly<Record<string, string>> = {
229	  "locked-out": "Still locked out: wait for the countdown",
230	  "already-solved": "You already solved this ruin",
231	  "not-at-ruin": "You are no longer at the ruin",
232	  "no-session": "Open the ruin again (R)",
233	  "in-duel": "Not during a duel",
234	};
235	
236	/** A verdict as the player reads it: the gold and the unlock, a wrong answer, or why it was refused. */
237	export function verdictLines(result: RuinResultMessage): Line[] {
238	  if (result.outcome === "solved") {
239	    const lines: Line[] = [{ text: `Ruin solved: +${result.gold} gold`, state: "solved" }];
240	    if (result.unlocked) lines.push({ text: "The island's rubbings are unlocked", state: "unlocked" });
241	    return lines;
242	  }
243	  if (result.outcome === "wrong") return [{ text: "Wrong answer: the ruin locks you out for a moment", state: "wrong" }];
244	  return [{ text: REFUSALS[result.reason ?? ""] ?? "The ruin did not take that answer", state: `refused:${result.reason ?? ""}` }];
245	}
246	
247	/** The lockout's countdown while it runs. */
248	export function lockoutLine(lockedUntil: number, worldTick: number): Line {
249	  const seconds = secondsUntil(lockedUntil, worldTick);
250	  return seconds > 0 ? { text: `Locked out: try again in ${seconds} s`, state: "locked", seconds } : { text: "", state: "none" };
251	}
252	
253	// ---------------------------------------------------------------------------------------------------------------
254	// The panel
255	
256	/** What the panel shows: hidden, or a clue with the entry, its lockout and the last verdict. */
257	export interface RuinPanelView {
258	  readonly hidden: boolean;
259	  readonly kind: string;
260	  readonly island: number;
261	  readonly tablets: readonly TabletView[];
262	  readonly grid: readonly (readonly CellView[])[];
263	  /** The cells the entered path visits, as "x,y". */
264	  readonly path: readonly string[];
265	  readonly chosen: readonly RuinSymbolName[];
266	  readonly entry: string;
267	  readonly canSubmit: boolean;
268	  readonly lockout: Line;
269	  readonly verdict: readonly Line[];
270	}
271	
272	export function ruinPanelView(opened: RuinOpenedMessage | undefined, entry: Entry, lockedUntil: number, worldTick: number, verdict: readonly Line[]): RuinPanelView {
273	  if (opened === undefined) {
274	    return { hidden: true, kind: "", island: -1, tablets: [], grid: [], path: [], chosen: [], entry: "", canSubmit: false, lockout: { text: "", state: "none" }, verdict };
275	  }
276	  const clue = opened.clue;
277	  const lockout = lockoutLine(lockedUntil, worldTick);
278	  return {
279	    hidden: false,
280	    kind: clue.kind,
281	    island: opened.island,
282	    tablets: clue.kind === "sequence" ? tabletsOf(clue) : [],
283	    grid: clue.kind === "navigation" ? gridOf(clue) : [],
284	    path: clue.kind === "navigation" ? pathCells(clue, entry.moves).map((cell) => `${cell.x},${cell.y}`) : [],
285	    chosen: entry.symbols,
286	    entry: entryText(clue, entry),
287	    canSubmit: attemptOf(clue, entry) !== undefined && lockout.state === "none",
288	    lockout,
289	    verdict,
290	  };
291	}
292	
293	/**
294	 * The ruin panel's behaviour, as `main.ts` wires it: R opens the ruin (when the HUD offers it), the clue shows the
295	 * panel, keys and clicks enter the answer, Enter or Submit sends it with a fresh request id, and the server's verdict
296	 * shows. The panel closes when the session does (casting off, a duel, a disconnect), on Escape, and after a solve (so
297	 * E collects at once).
298	 */
299	export class RuinPanel {
300	  private opened: RuinOpenedMessage | undefined;
301	  private entry: Entry = EMPTY_ENTRY;
302	  private lockedUntil = 0;
303	  private verdict: readonly Line[] = [];
304	  /** The panel saw its session open on the server, so a closed session closes it. */
305	  private sessionSeen = false;
306	  private requests = 0;
307	  private status: RuinStatus | undefined;
308	  private worldTick = 0;
309	
310	  constructor(
311	    private readonly send: (type: string, message: unknown) => void,
312	    private readonly render: (view: RuinPanelView) => void,
313	    private readonly requestPrefix: string = Date.now().toString(36),
314	  ) {}
315	
316	  get isOpen(): boolean {
317	    return this.opened !== undefined;
318	  }
319	
320	  /** The last verdict, for the HUD while the panel is closed. */
321	  get lastVerdict(): readonly Line[] {
322	    return this.verdict;
323	  }
324	
325	  /** The latest private status and world tick: a session the server closed closes the panel. */
326	  update(status: RuinStatus | undefined, worldTick: number): void {
327	    this.status = status;
328	    this.worldTick = worldTick;
329	    if (this.opened !== undefined && status?.ruinOpen === true) this.sessionSeen = true;
330	    if (this.opened !== undefined && this.sessionSeen && status?.ruinOpen !== true) this.close();
331	    if (status?.ruin === "") this.verdict = [];
332	    this.draw();
333	  }
334	
335	  /** The server's clue (only ever for this player's own open ruin). */
336	  clue(message: unknown): void {
337	    const opened = parseRuinClueMessage(message);
338	    if (opened === undefined || opened.solved) return;
339	    if (this.opened?.island !== opened.island) this.entry = EMPTY_ENTRY;
340	    this.opened = opened;
341	    this.lockedUntil = opened.lockedUntil;
342	    this.sessionSeen = this.status?.ruinOpen === true;
343	    this.draw();
344	  }
345	
346	  /** The server's verdict on one of this player's answers. */
347	  result(message: unknown): void {
348	    const result = parseRuinResultMessage(message);
349	    if (result === undefined) return;
350	    this.verdict = verdictLines(result);
351	    this.lockedUntil = Math.max(this.lockedUntil, result.lockedUntil);
352	    if (result.outcome === "wrong") this.entry = EMPTY_ENTRY;
353	    if (result.outcome === "solved") this.close();
354	    this.draw();
355	  }
356	
357	  /** A key in the page: R opens the ruin; the panel's own keys when it is open. True when the key was the panel's. */
358	  keydown(event: Pick<KeyboardEvent, "code" | "repeat">): boolean {
359	    if (this.opened === undefined) {
360	      if (event.code !== "KeyR" || event.repeat || !canOpenRuin(this.status)) return false;
361	      this.verdict = [];
362	      this.send(RuinMessageType.Open, {} satisfies OpenRuinMessage);
363	      return true;
364	    }
365	    const key = panelKey(this.opened.clue.kind, event.code);
366	    if (key === undefined) return false;
367	    this.press(key);
368	    return true;
369	  }
370	
371	  /** A click on a tablet or a button, or a key the panel read. */
372	  press(key: PanelKey): void {
373	    const opened = this.opened;
374	    if (opened === undefined) return;
375	    if (key.kind === "close") this.close();
376	    else if (key.kind === "submit") this.submit(opened.clue);
377	    else this.entry = enter(opened.clue, this.entry, key);
378	    this.draw();
379	  }
380	
381	  private submit(clue: RuinClueMessage): void {
382	    const attempt = attemptOf(clue, this.entry);
383	    if (attempt === undefined || lockoutLine(this.lockedUntil, this.worldTick).state !== "none") return;
384	    this.send(RuinMessageType.Answer, { requestId: `${this.requestPrefix}-${++this.requests}`, attempt } satisfies AnswerRuinMessage);
385	  }
386	
387	  private close(): void {
388	    this.opened = undefined;
389	    this.entry = EMPTY_ENTRY;
390	    this.sessionSeen = false;
391	  }
392	
393	  private draw(): void {
394	    this.render(ruinPanelView(this.opened, this.entry, this.lockedUntil, this.worldTick, this.verdict));
395	  }
396	}
397	
398	function field(root: ParentNode, id: string): HTMLElement {
399	  const element = root.querySelector<HTMLElement>(`[data-testid="${id}"]`);
400	  if (element === null) throw new Error(`missing ruin field ${id}`);
401	  return element;
402	}
403	
404	function write(element: HTMLElement, line: Line): void {
405	  element.textContent = line.text;
406	  element.dataset["state"] = line.state;
407	  if (line.seconds === undefined) delete element.dataset["seconds"];
408	  else element.dataset["seconds"] = String(line.seconds);
409	}
410	
411	/** Writes the panel into the page: the tablets or the grid (rebuilt only when the clue changes), the entry and lines. */
412	export function applyRuin(root: ParentNode, view: RuinPanelView): void {
413	  const panel = field(root, "ruin-panel");
414	  panel.hidden = view.hidden;
415	  panel.dataset["kind"] = view.kind;
416	  panel.dataset["island"] = String(view.island);
417	  const tablets = field(root, "ruin-tablets");
418	  tablets.hidden = view.kind !== "sequence";
419	  const tabletKey = view.tablets.map((tablet) => `${tablet.symbol}:${tablet.text}`).join("|");
420	  if (tablets.dataset["clue"] !== tabletKey) {
421	    tablets.dataset["clue"] = tabletKey;
422	    tablets.replaceChildren(
423	      ...view.tablets.map((tablet) => {
424	        const item = document.createElement("li");
425	        item.dataset["testid"] = "ruin-tablet";
426	        item.dataset["symbol"] = tablet.symbol;
427	        const button = document.createElement("button");
428	        button.type = "button";
429	        button.dataset["symbol"] = tablet.symbol;
430	        button.setAttribute("aria-label", `${tablet.key}: ${tablet.name}`);
431	        button.textContent = `${tablet.key} ${tablet.glyph} ${tablet.name}`;
432	        const text = document.createElement("span");
433	        text.className = "inscription";
434	        text.dataset["testid"] = "ruin-inscription";
435	        text.textContent = tablet.text;
436	        item.append(button, text);
437	        return item;
438	      }),
439	    );
440	  }
441	  for (const item of tablets.querySelectorAll<HTMLElement>("li[data-symbol]")) {
442	    const order = view.chosen.indexOf(item.dataset["symbol"] as RuinSymbolName);
443	    item.dataset["chosen"] = order < 0 ? "" : String(order + 1);
444	  }
445	  const grid = field(root, "ruin-grid");
446	  grid.hidden = view.kind !== "navigation";
447	  const gridKey = view.grid.map((row) => row.map((cell) => cell.kind[0]).join("")).join("/");
448	  if (grid.dataset["clue"] !== gridKey) {
449	    grid.dataset["clue"] = gridKey;
450	    grid.style.setProperty("--size", String(view.grid.length));
451	    grid.replaceChildren(
452	      ...view.grid.flat().map((cell) => {
453	        const square = document.createElement("span");
454	        square.className = "cell";
455	        square.dataset["cell"] = `${cell.x},${cell.y}`;
456	        square.dataset["kind"] = cell.kind;
457	        square.textContent = cell.kind === "start" ? "S" : cell.kind === "goal" ? "G" : cell.kind === "blocked" ? "▩" : "";
458	        return square;
459	      }),
460	    );
461	  }
462	  const path = new Set(view.path);
463	  for (const square of grid.querySelectorAll<HTMLElement>("[data-cell]")) square.dataset["path"] = String(path.has(square.dataset["cell"]!));
464	  grid.dataset["path"] = view.path.join(" ");
465	  const entry = field(root, "ruin-entry");
466	  entry.textContent = view.entry;
467	  entry.dataset["symbols"] = view.chosen.join(",");
468	  (field(root, "ruin-submit") as HTMLButtonElement).disabled = !view.canSubmit;
469	  write(field(root, "ruin-lockout"), view.lockout);
470	  write(field(root, "ruin-verdict"), view.verdict[0] ?? { text: "", state: "none" });
471	}
472	
473	/** The HUD's ruin lines: the ruin where the player is moored, the last verdict, and the ruins of islands in sight. */
474	export function renderRuinHud(root: ParentNode, model: { status: RuinStatus | undefined; verdict: readonly Line[]; sighted: Line }): void {
475	  write(field(root, "hud-ruin"), ruinLine(model.status));
476	  write(field(root, "hud-ruin-verdict"), {
477	    text: model.verdict.map((line) => line.text).join(". "),
478	    state: model.verdict.length === 0 ? "none" : model.verdict.map((line) => line.state).join(","),
479	  });
480	  write(field(root, "hud-ruins-sighted"), model.sighted);
481	}
