1	import { expect, test } from "@playwright/test";
2	import { seaMap } from "../../packages/content/src/index.js";
3	import { readGrid, readSequence, type ReadTablet } from "../../packages/test-tools/src/ruinReader.js";
4	import { attachScreenshot, createMatch, nextMatchRuins, place, readout, selfId, startWithCompanion } from "./helpers.js";
5	
6	/**
7	 * §3's ruins in the browser. The browser server opens every island (test-only); these matches ask for locked ruins of
8	 * a pinned kind instead (`nextMatchRuins`). The test reads the clue off the page, as a player reads it, works the
9	 * answer out from what it read (`ruinReader`: never from the server's puzzle), enters it with the keyboard and clicks,
10	 * and sees the gold, the unlock and then the collection.
11	 */
12	
13	const PALM_WEST = seaMap.docks.find((dock) => dock.island === 0)!;
14	const EMBER_EAST = seaMap.docks.find((dock) => dock.island === 1)!;
15	const SYMBOLS = ["sun", "moon", "tide", "storm", "anchor", "skull"] as const;
16	const PLACES: Readonly<Record<string, number>> = { first: 0, "in the middle": 1, last: 2 };
17	
18	/** An inscription as a hint, read the way a player reads "Tide comes right after Sun". */
19	function readInscription(symbol: string, text: string): ReadTablet {
20	  const name = (word: string) => word.toLowerCase();
21	  const rules: [RegExp, (match: RegExpExecArray) => ReadTablet["hint"]][] = [
22	    [/^\w+ is not in the sequence$/, () => ({ relation: "absent", other: null, position: null })],
23	    [/^\w+ is in the sequence$/, () => ({ relation: "present", other: null, position: null })],
24	    [/^\w+ does not come (first|last|in the middle)$/, (match) => ({ relation: "not-at", other: null, position: PLACES[match[1]!]! })],
25	    [/^\w+ comes (first|last|in the middle)$/, (match) => ({ relation: "at", other: null, position: PLACES[match[1]!]! })],
26	    [/^\w+ comes right (after|before) (\w+)$/, (match) => ({ relation: `right-${match[1]}`, other: name(match[2]!), position: null })],
27	    [/^\w+ comes somewhere (after|before) (\w+)$/, (match) => ({ relation: match[1]!, other: name(match[2]!), position: null })],
28	  ];
29	  for (const [pattern, hint] of rules) {
30	    const match = pattern.exec(text);
31	    if (match !== null) return { symbol, hint: hint(match) };
32	  }
33	  throw new Error(`cannot read the inscription "${text}"`);
34	}
